import test from 'node:test';
import assert from 'node:assert/strict';
import {newGame,save,restore} from './simulation.js';
import {startSurvival,returnSurvivalSortie,launchSurvivalSortie} from './survival-base.js';
import {thinkingCampaign} from './survival-thinking-fixtures.js';
import {refreshSurvivalThinking,respondSurvivalThinking,survivalThinkingView,survivalThinkingCandidates,thinkingConsent,thinkingSupply,thinkingPlanLine} from './survival-thinking.js';
import {executeSurvivalThinking,thinkingStepBlocked} from './survival-thinking-actions.js';
import {survivalPage} from './survival-ui.js';
import {survivalThinkingPage} from './survival-thinking-ui.js';
import {combatPackAction} from './survival-pack.js';
import {decideSupplyDebate} from './supply-debate.js';
import {supplyRescueRoute} from './supply-debate-fixtures.js';
import {gridAct,endGridTurn} from './combat-grid.js';
const plan=(s,key='ally')=>survivalThinkingView(s).find(p=>p.speaker===key);
test('solo and absent characters cannot produce imaginary proposals; only actual current companions speak',()=>{let s=startSurvival(newGame());assert.equal(survivalThinkingView(s).length,0);s=thinkingCampaign();assert.equal(survivalThinkingView(s).length,2);s.survivalRun.members[1].deployment='elsewhere';s=refreshSurvivalThinking(s);assert.ok(!survivalThinkingView(s).some(p=>p.speaker==='ally'));assert.ok(!survivalThinkingPage(s).includes('data-thinking-plan="'+plan(thinkingCampaign()).id+'"'));});
test('same shortage produces distinct scored routes and actual failure memory changes future choice',()=>{let s=thinkingCampaign(null,'supply');assert.equal(plan(s).goal,'supply:kiosk');assert.equal(plan(s,'member-2').goal,'supply:convenience');s.survivalRun.members[2].thinkingLearning={caution:30};s=refreshSurvivalThinking(s);assert.equal(plan(s,'member-2').goal,'supply:kiosk');const options=survivalThinkingCandidates(s,s.survivalRun.members[2]);assert.ok(options.every(o=>o.steps.length>0));});
test('procedural conversations use observed facts and witnessed memories with stable save/render behavior',()=>{let s=thinkingCampaign(),p=plan(s),before=save(s);for(let i=0;i<3;i++){survivalPage(s,'thinking');survivalThinkingPage(s);thinkingConsent(s,p);thinkingPlanLine(s,p);}assert.equal(save(s),before);s=respondSurvivalThinking(s,p.id,'why');assert.match(plan(s).dialogue.at(-1).text,/먹|상처|힘들/);assert.ok(!/수분.*100|행동력|실제로/.test(plan(s).dialogue.at(-1).text));assert.match(plan(s).evidence,/20/);assert.throws(()=>respondSurvivalThinking(s,p.id,'why'));s=respondSurvivalThinking(s,p.id,'risk');assert.match(plan(s).dialogue.at(-1).text,/물건|상처|붕대/);assert.deepEqual(restore(save(s)),s);assert.equal(thinkingPlanLine(s,p),thinkingPlanLine(restore(save(s)),p));});
test('accepting is a commitment, not free care, supplies or automatic actions',()=>{let s=thinkingCampaign(),p=plan(s),resources=structuredClone(s.survivalRun.resources),member=structuredClone(s.survivalRun.members[1]),school=structuredClone(s.relations);s=respondSurvivalThinking(s,p.id,'accept');assert.equal(plan(s).status,'accepted');assert.deepEqual(s.survivalRun.resources,resources);assert.deepEqual(s.survivalRun.members[1],member);assert.deepEqual(s.relations,school);assert.equal(s.survivalRun.activeSortie,null);});
test('generated recovery sequence consumes actual water food bandage and action and remembers real completion',()=>{let s=thinkingCampaign(),p=plan(s),id=p.id,water=thinkingSupply(s.survivalRun,'water'),food=thinkingSupply(s.survivalRun,'food'),bandage=thinkingSupply(s.survivalRun,'bandage'),actions=s.survivalRun.actions;s=respondSurvivalThinking(s,id,'accept');assert.deepEqual(plan(s).steps.map(q=>q.kind),['drink','eat','treat']);s=executeSurvivalThinking(s,id);assert.equal(thinkingSupply(s.survivalRun,'water'),water-1);assert.equal(plan(s).steps[0].status,'completed');s=executeSurvivalThinking(restore(save(s)),id);assert.equal(thinkingSupply(s.survivalRun,'food'),food-1);s=executeSurvivalThinking(s,id);const done=s.survivalRun.thinking.plans.find(p=>p.id===id);assert.equal(done.status,'completed');assert.ok(done.steps.every(q=>q.status==='completed'));assert.equal(thinkingSupply(s.survivalRun,'bandage'),bandage-1);assert.equal(s.survivalRun.actions,actions-1);assert.equal(s.survivalRun.members[1].injury,1);assert.equal(s.survivalRun.members[1].thinkingMemories.filter(m=>m.id===id).length,1);const saved=save(s);s=refreshSurvivalThinking(s);assert.equal(save(s),saved);assert.throws(()=>executeSurvivalThinking(s,id));});
test('alternative proposal persists, has different real steps, and conversation cannot farm relationship points',()=>{let s=thinkingCampaign(null,'supply'),p=plan(s),goal=p.goal,bonds=structuredClone(s.survivalRun.parties.bonds),school=structuredClone(s.relations);s=respondSurvivalThinking(s,p.id,'alternative');assert.notEqual(plan(s).goal,goal);const alt=plan(s).goal;s=refreshSurvivalThinking(s);assert.equal(plan(s).goal,alt);s=respondSurvivalThinking(s,p.id,'companions');s=respondSurvivalThinking(s,p.id,'why');assert.deepEqual(s.survivalRun.parties.bonds,bonds);assert.deepEqual(s.relations,school);});
test('actual companion can refuse a field plan; changed consent is rechecked at execution',()=>{let s=thinkingCampaign(null,'supply'),p=plan(s);s.survivalRun.parties.bonds['member:member-2']={trust:0,tension:20};assert.equal(thinkingConsent(s,p).find(v=>v.key==='member-2').agrees,false);const before=save(s);assert.throws(()=>respondSurvivalThinking(s,p.id,'accept'),/불편/);assert.equal(save(s),before);assert.throws(()=>launchSurvivalSortie(s,'kiosk'),/불편/);assert.equal(save(s),before);s.survivalRun.parties.bonds['member:member-2'].tension=0;s=respondSurvivalThinking(s,p.id,'accept');s.survivalRun.members[2].injury=3;assert.match(thinkingStepBlocked(s,plan(s)),/치료/);assert.throws(()=>executeSurvivalThinking(s,p.id));assert.equal(s.survivalRun.activeSortie,null);});
test('changed resources block actions atomically and preparing cannot manufacture inventory',()=>{let s=thinkingCampaign(),p=plan(s);s=respondSurvivalThinking(s,p.id,'accept');s.survivalRun.resources.water=0;s.survivalRun.kit.items.water=0;const before=save(s);assert.throws(()=>executeSurvivalThinking(s,p.id));assert.equal(save(s),before);s=thinkingCampaign(null,'supply');p=plan(s);s=respondSurvivalThinking(s,p.id,'accept');const rations=thinkingSupply(s.survivalRun,'food');s=executeSurvivalThinking(s,p.id);assert.equal(plan(s).steps[0].status,'completed');assert.equal(thinkingSupply(s.survivalRun,'food'),rations);assert.equal(s.survivalRun.activeSortie,null);s=executeSurvivalThinking(s,p.id);assert.equal(s.survivalRun.activeSortie.kind,'kiosk');assert.equal(plan(s).status,'accepted');});
test('failed real sortie records unfinished goal and increases caution exactly once',()=>{let s=thinkingCampaign(null,'supply'),p=plan(s,'member-2'),id=p.id;s=respondSurvivalThinking(s,id,'accept');s=executeSurvivalThinking(s,id);s=executeSurvivalThinking(s,id);s=returnSurvivalSortie(s,{abandon:true});assert.equal(s.survivalRun.thinking.plans.find(p=>p.id===id).status,'failed');assert.equal(s.survivalRun.members[2].thinkingLearning.caution,6);const count=s.survivalRun.members[2].thinkingMemories.length;s=refreshSurvivalThinking(s);assert.equal(s.survivalRun.members[2].thinkingMemories.length,count);assert.ok(s.survivalRun.thinking.plans.find(p=>p.id===id).result.includes('중단'));});
test('watch plan assigns a real job and stays active until an actual night is completed',()=>{let s=thinkingCampaign(null,'watch'),p=plan(s),id=p.id;assert.equal(p.goal,'watch');s=respondSurvivalThinking(s,id,'accept');s=executeSurvivalThinking(s,id);assert.equal(s.survivalRun.members[1].job,'watch');assert.equal(plan(s).steps[0].status,'completed');assert.equal(plan(s).status,'accepted');s=executeSurvivalThinking(restore(save(s)),id);assert.equal(s.survivalRun.thinking.plans.find(p=>p.id===id).status,'completed');assert.equal(s.survivalRun.day,5);});
test('deferral suppresses that goal for the day, conversation does not cost time, old saves migrate without rewriting relationships',()=>{let s=thinkingCampaign(),p=plan(s),goal=p.goal,day=s.survivalRun.day,actions=s.survivalRun.actions;s=respondSurvivalThinking(s,p.id,'defer');assert.ok(!survivalThinkingView(s).some(q=>q.speaker==='ally'&&q.goal===goal));assert.equal(s.survivalRun.day,day);assert.equal(s.survivalRun.actions,actions);delete s.survivalRun.thinking;const school=structuredClone(s.relations);s=refreshSurvivalThinking(restore(save(s)));assert.equal(s.survivalRun.thinking.version,1);assert.deepEqual(s.relations,school);});
test('planned supply mission only succeeds after live combat and real food brought home',()=>{let s=thinkingCampaign(null,'supply'),p=plan(s),id=p.id;s=respondSurvivalThinking(s,id,'accept');s=executeSurvivalThinking(s,id);s=executeSurvivalThinking(s,id);for(const [key,action,target] of supplyRescueRoute){if(key==='end')s=endGridTurn(s);else if(key==='decision')s=decideSupplyDebate(s,action);else if(key==='packLeave'){s=combatPackAction(s,'take','food');s=combatPackAction(s,'leave');}else s=gridAct(s,key,action,target);}assert.equal(s.combatTrial.status,'escaped');s=returnSurvivalSortie(restore(save(s)));assert.equal(s.survivalRun.thinking.plans.find(p=>p.id===id).status,'completed');assert.equal(s.survivalRun.kit.items.food,1);assert.match(s.survivalRun.thinking.plans.find(p=>p.id===id).steps[1].result,/실제/);});
test('moving proposer out of the actual party hides their proposal and cannot launch their field plan',async()=>{const {moveSurvivalPartyMember}=await import('./survival-parties.js');let s=thinkingCampaign(null,'supply'),p=plan(s);s=respondSurvivalThinking(s,p.id,'accept');s=moveSurvivalPartyMember(s,'ally','reserve');s=refreshSurvivalThinking(s);assert.ok(!survivalThinkingView(s).some(p=>p.speaker==='ally'));assert.throws(()=>executeSurvivalThinking(s,p.id),/편성/);});
test('unready expedition prompts a nearby search alternative that only finishes after actual loot is selected',async()=>{const {takeSurvivalLoot,leaveSurvivalLoot}=await import('./survival-pack.js');let s=thinkingCampaign(null,'supply');s.survivalRun.members[0].injury=3;s.survivalRun.resources.bandage=0;s.survivalRun.kit.items.bandage=0;s=refreshSurvivalThinking(s);let p=plan(s);assert.equal(p.goal,'search');const id=p.id;s=respondSurvivalThinking(s,id,'accept');const actions=s.survivalRun.actions;s=executeSurvivalThinking(s,id);assert.ok(s.survivalRun.kit.pending);assert.equal(s.survivalRun.actions,actions-1);assert.equal(plan(s).status,'accepted');s=takeSurvivalLoot(s,'food');s=leaveSurvivalLoot(s);assert.equal(s.survivalRun.thinking.plans.find(p=>p.id===id).status,'completed');assert.equal(s.survivalRun.kit.items.food,1);});
test('food recovery does not falsely count as the planned hide/rest action',async()=>{const {careSurvivalMember}=await import('./survival-pack.js');let s=thinkingCampaign(null,'watch');s.survivalRun.threat=20;s.survivalRun.members[1].fatigue=70;s=refreshSurvivalThinking(s);const p=plan(s),id=p.id;assert.equal(p.goal,'rest');s=respondSurvivalThinking(s,id,'accept');s=careSurvivalMember(s,'ally','food');assert.equal(s.survivalRun.thinking.plans.find(p=>p.id===id).status,'accepted');s=executeSurvivalThinking(s,id);assert.equal(s.survivalRun.thinking.plans.find(p=>p.id===id).status,'completed');});
test('watch commitment does not succeed if actual night role was changed back to rest',async()=>{const {assignSurvivalJob,finishSurvivalDay}=await import('./survival-base.js');let s=thinkingCampaign(null,'watch');const id=plan(s).id;s=respondSurvivalThinking(s,id,'accept');s=executeSurvivalThinking(s,id);s=assignSurvivalJob(s,'ally','rest');s=finishSurvivalDay(s);assert.equal(s.survivalRun.lastNight.roles.ally,'rest');assert.equal(s.survivalRun.thinking.plans.find(p=>p.id===id).status,'failed');});
test('earlier unrelated loot cannot be mistaken for the planned sortie bringing supplies home',async()=>{const {survivalAction}=await import('./survival-base.js');const {takeSurvivalLoot,leaveSurvivalLoot}=await import('./survival-pack.js');let s=thinkingCampaign(null,'supply'),id=plan(s).id;s=respondSurvivalThinking(s,id,'accept');s=survivalAction(s,'search');s=takeSurvivalLoot(s,'food');s=leaveSurvivalLoot(s);s=executeSurvivalThinking(s,id);s=executeSurvivalThinking(s,id);assert.equal(s.survivalRun.thinking.plans.find(p=>p.id===id).departure.observation.food,1);for(const [key,action,target] of supplyRescueRoute){if(key==='end')s=endGridTurn(s);else if(key==='decision')s=decideSupplyDebate(s,action);else if(key==='packLeave')s=combatPackAction(s,'leave');else s=gridAct(s,key,action,target);}s=returnSurvivalSortie(s);assert.equal(s.survivalRun.thinking.plans.find(p=>p.id===id).status,'failed');assert.equal(s.survivalRun.kit.items.food,1);});
